#!/usr/bin/env bash

set -e
set -x
shopt -s dotglob

readonly name="CLI11"
readonly ownership="CLI11 Upstream <robot@adios2>"
readonly subtree="thirdparty/CLI11/CLI11_wrapper"
readonly repo="https://github.com/CLIUtils/CLI11.git"
readonly tag="v2.7.2"
readonly shortlog="true"
readonly exact_tree_match="false"

# CLI11's single-header build (include/CLI/CLI.hpp) is generated by CI and
# published only as a release asset, not committed to the upstream tree, so
# it is downloaded directly instead of using the git_archive helper.
extract_source () {
    mkdir -p "$extractdir/$name-reduced/include/CLI"
    curl -sL -o "$extractdir/$name-reduced/include/CLI/CLI.hpp" \
        "https://github.com/CLIUtils/CLI11/releases/download/$tag/CLI11.hpp"
    cp LICENSE "$extractdir/$name-reduced/LICENSE"
}

. "${BASH_SOURCE%/*}/../update-common.sh"
